#!/usr/bin/env python3
"""Golden vectors for Tuner's AirPlay pairing code, generated by pyatv 0.18.0 (owner: CAST-1;
DESIGN §40 §14.3 "Anchors against self-consistency"). Dev only: never run by CI or the tests.

usage (a throwaway venv, never system-wide; `-I` keeps the checkout off sys.path):
    python -m venv /tmp/pyatv-venv && /tmp/pyatv-venv/bin/pip install pyatv==0.18.0
    /tmp/pyatv-venv/bin/python -I scripts/cast/pyatv_vectors.py \
        tests/fixtures/cast/vectors/pyatv_0_18_0.json

pyatv's own code produces every value: its TLV8 writer, its SRP (srptools), its client
pair-setup / pair-verify procedures talking to its own `BaseAirPlayServerAuth` through an
in-memory HTTP stand-in, its HKDF, its HAP frame cipher and its plist body encoder. Randomness
is pinned (os.urandom for the client keys, srptools' salt) so the output is deterministic; the
accessory is pyatv's test identity (SERVER_IDENTIFIER, PRIVATE_KEY = 32 x 0xAA, PIN 1111), which
pyatv also uses as the SRP `b` and the accessory's X25519 key. pyatv uses the controller's
Ed25519 seed as the SRP `a`, so the vectors do too.

Both sides of Tuner's code are checked against the file: the client (`src/cast/airplay/pair.rs`
and friends) and the fake receiver's server halves (DESIGN §40 §14.3).

pyatv is MIT-licensed, (c) 2020 Pierre Ståhl; see THIRD_PARTY_NOTICES.md.
"""
import asyncio
import datetime as dt
import json
import plistlib
import sys
import types

import srptools
import pyatv.const
from pyatv.auth import hap_srp
from pyatv.auth.hap_session import HAPSession
from pyatv.auth.hap_srp import SRPAuthHandler, hkdf_expand
from pyatv.auth.hap_tlv8 import TlvValue, read_tlv, write_tlv
from pyatv.auth.server_auth import PIN_CODE, PRIVATE_KEY, SERVER_IDENTIFIER
from pyatv.protocols.airplay.auth import CONTROL_INPUT_INFO, CONTROL_OUTPUT_INFO, CONTROL_SALT
from pyatv.protocols.airplay.auth.hap import AirPlayHapPairSetupProcedure, AirPlayHapPairVerifyProcedure
from pyatv.protocols.airplay.ap2_session import EVENTS_READ_INFO, EVENTS_SALT, EVENTS_WRITE_INFO
from pyatv.protocols.airplay.server_auth import BaseAirPlayServerAuth
from pyatv.protocols.airplay.utils import encode_plist_body
from pyatv.support import opack
from pyatv.support.http import HttpRequest

assert pyatv.const.__version__ == "0.18.0", f"pyatv {pyatv.const.__version__}: the vectors are pinned to 0.18.0"

CONTROLLER_ID = "8E9F4C2D-6B1A-4E7F-9C3B-2A5D8E1F0B6C"  # a fixed pairing UUID
CONTROLLER_SEED = bytes(range(1, 33))                 # Ed25519 seed, also SRP `a` (pyatv)
CLIENT_EPHEMERAL = bytes(range(0x40, 0x60))           # X25519 secret for pair-verify
SALT = bytes(range(0xA0, 0xB0))                       # first byte non-zero (srptools keeps salts as ints)
ACL = b"\xe1\x57com.apple.ScreenCapture\x01"          # HKP 5 M5 TLV 0x12 (DESIGN §40 §7.2)


def pattern(n, seed=0):
    return bytes((i * 7 + seed) % 251 for i in range(n))


def h(b):
    return b.hex()


def srp_hex(v):
    """srptools hands out hex as `str` (ints) or `bytes` (hashes)."""
    return v.decode() if isinstance(v, bytes) else v


def urandom_queue(*values):
    queue = list(values)

    def urandom(n):
        v = queue.pop(0)
        assert len(v) == n
        return v

    return types.SimpleNamespace(urandom=urandom)


class Accessory(BaseAirPlayServerAuth):
    """pyatv's server half with its test identity; records the keys it enables."""

    def enable_encryption(self, output_key, input_key):
        self.enabled = (output_key, input_key)


class FakeHttp:
    """Routes the procedures' POSTs to the accessory and logs (path, request, reply)."""

    def __init__(self, server):
        self.server = server
        self.log = []

    async def post(self, path, body=None, headers=None, **_):
        headers = {k: str(v) for k, v in (headers or {}).items()}
        req = HttpRequest("POST", path, "HTTP", "1.1", headers, body or b"")
        route = {
            "/pair-pin-start": self.server.handle_pair_pin_start,
            "/pair-setup": self.server.handle_pair_setup,
            "/pair-verify": self.server.handle_pair_verify,
        }[path]
        resp = route(req)
        self.log.append((path, body or b"", resp.body))
        return resp


def typed(v):
    """A plist value as tagged JSON (the Rust test rebuilds `bplist::Value` from it)."""
    if isinstance(v, bool):
        return {"bool": v}
    if isinstance(v, int):
        return {"int": v}
    if isinstance(v, float):
        return {"real": v}
    if isinstance(v, str):
        return {"string": v}
    if isinstance(v, bytes):
        return {"data": h(v)}
    if isinstance(v, plistlib.UID):
        return {"uid": v.data}
    if isinstance(v, dt.datetime):
        return {"date": (v - dt.datetime(2001, 1, 1)).total_seconds()}
    if isinstance(v, list):
        return {"array": [typed(x) for x in v]}
    if isinstance(v, dict):
        return {"dict": [[k, typed(x)] for k, x in sorted(v.items())]}  # plistlib sorts keys
    raise TypeError(type(v))


async def main(out_path):
    srptools.SRPContext.generate_salt = lambda self: int.from_bytes(SALT, "big")
    server = Accessory("Living Room")
    http = FakeHttp(server)

    # ---- pair-setup (HKP 3), pyatv's client procedure against pyatv's accessory
    setup_srp = SRPAuthHandler()
    setup_srp.pairing_id = CONTROLLER_ID.encode()
    hap_srp.os = urandom_queue(CONTROLLER_SEED, bytes(32))
    setup = AirPlayHapPairSetupProcedure(http, setup_srp)
    await setup.start_pairing()
    creds = await setup.finish_pairing("", PIN_CODE, None)
    (_, _, _), (_, m1, m2), (_, m3, m4), (_, m5, m6) = http.log
    assert creds.atv_id == SERVER_IDENTIFIER.encode() and creds.ltsk == CONTROLLER_SEED

    sess = setup_srp._session
    ctx = sess._context
    srp_s = ctx.get_client_premaster_secret(sess._password_hash, sess._server_public, sess._this_private, sess._common_secret)
    k_bytes = bytes.fromhex(srp_hex(sess.key))

    # HKP 5: the same exchange, M5 carries the ScreenCapture ACL (pyatv's `additional_data`)
    assert opack.pack({"com.apple.ScreenCapture": True}) == ACL
    m5_hkp5 = write_tlv({TlvValue.SeqNo: b"\x05", TlvValue.EncryptedData: setup_srp.step3(additional_data={0x12: ACL})})

    # ---- pair-verify, then the control and event keys
    http.log.clear()
    verify_srp = SRPAuthHandler()
    hap_srp.os = urandom_queue(bytes(32), CLIENT_EPHEMERAL)
    verifier = AirPlayHapPairVerifyProcedure(http, verify_srp, creds)
    await verifier.verify_credentials()
    (_, v1, v2), (_, v3, v4) = http.log
    control_write, control_read = verifier.encryption_keys(CONTROL_SALT, CONTROL_OUTPUT_INFO, CONTROL_INPUT_INFO)
    events_write, events_read = verifier.encryption_keys(EVENTS_SALT, EVENTS_READ_INFO, EVENTS_WRITE_INFO)
    assert server.enabled == (control_read, control_write)  # the accessory swaps them
    shared = verify_srp._shared

    # ---- HAP frames: our 1500-byte write (1024 + 476) and the TV's long single frames
    ours = HAPSession()
    ours.enable(control_write, control_read)
    sealed = ours.encrypt(pattern(1500))
    tv = HAPSession()
    tv.enable(control_read, control_write)
    inbound = b""
    for n in (1500, 16384):
        length = n.to_bytes(2, "little")
        inbound += length + tv.chacha20.encrypt(pattern(n, n), aad=length)
    assert ours.decrypt(inbound) == pattern(1500, 1500) + pattern(16384, 16384)

    labels = [
        ("Pair-Setup-Encrypt-Salt", "Pair-Setup-Encrypt-Info"),
        ("Pair-Setup-Controller-Sign-Salt", "Pair-Setup-Controller-Sign-Info"),
        ("Pair-Setup-Accessory-Sign-Salt", "Pair-Setup-Accessory-Sign-Info"),
        ("Pair-Verify-Encrypt-Salt", "Pair-Verify-Encrypt-Info"),
        (CONTROL_SALT, CONTROL_OUTPUT_INFO),
        (CONTROL_SALT, CONTROL_INPUT_INFO),
        (EVENTS_SALT, EVENTS_WRITE_INFO),
        (EVENTS_SALT, EVENTS_READ_INFO),
    ]
    hkdf = [
        {"ikm": name, "salt": salt, "info": info, "out": h(hkdf_expand(salt, info, ikm))}
        for name, ikm in (("srp_k", k_bytes), ("verify_shared", shared))
        for salt, info in labels
    ]

    tlv_cases = [
        {TlvValue.Method: b"\x00", TlvValue.SeqNo: b"\x01"},
        {TlvValue.SeqNo: b"\x03", TlvValue.PublicKey: pattern(384), TlvValue.Proof: pattern(64, 1)},
        {TlvValue.SeqNo: b"\x06", TlvValue.EncryptedData: pattern(600, 2), 0x11: pattern(159, 3)},
    ]
    tlv8 = []
    for case in tlv_cases:
        encoded = write_tlv(case)
        assert read_tlv(encoded) == case
        tlv8.append({"items": [[int(t), h(v)] for t, v in case.items()], "encoded": h(encoded)})

    plists = [
        {"streams": []},
        {"params": {"data": encode_plist_body({"type": "playbackInfo", "kind": "request", "messageID": 7})}},
        {
            "bool_t": True,
            "bool_f": False,
            "int_8": 1,
            "int_16": 300,
            "int_32": 70000,
            "int_64": 1 << 40,
            "neg": -5,
            "real": 1.5,
            "str": "Tuner",
            "long_str": "x" * 20,
            "unicode": "Wohnzimmer – TV",
            "data": bytes([0, 1, 2]),
            "array": [1, "a", 1, "a", True],
            "nested": {"k": [{"x": 0.25}], "empty": {}},
            "date": dt.datetime(2026, 10, 12, 12, 0, 0),
            "uid": plistlib.UID(5),
        },
    ]
    bplist = [{"value": typed(p), "encoded": h(encode_plist_body(p))} for p in plists]

    out = {
        "_comment": [
            "Generated by scripts/cast/pyatv_vectors.py with pyatv 0.18.0 (MIT, (c) 2020 Pierre Ståhl;",
            "see THIRD_PARTY_NOTICES.md). Every value was produced by pyatv's own code. Do not edit.",
        ],
        "pyatv": pyatv.const.__version__,
        "inputs": {
            "pin": str(PIN_CODE),
            "controller_id": CONTROLLER_ID,
            "controller_seed": h(CONTROLLER_SEED),
            "srp_a": h(CONTROLLER_SEED),
            "client_ephemeral": h(CLIENT_EPHEMERAL),
            "accessory_id": SERVER_IDENTIFIER,
            "accessory_seed": h(PRIVATE_KEY),
            "srp_b": h(PRIVATE_KEY),
            "accessory_ephemeral": h(PRIVATE_KEY),
            "salt": h(SALT),
            "acl": h(ACL),
        },
        "tlv8": tlv8,
        "srp": {
            "k": h(srptools.utils.int_to_bytes(ctx._mult)),
            "x": h(srptools.utils.int_to_bytes(sess._password_hash)),
            "verifier": h(srptools.utils.int_to_bytes(server.session._password_verifier)),
            "A": srp_hex(sess.public),
            "B": srp_hex(server.session.public),
            "u": h(srptools.utils.int_to_bytes(sess._common_secret)),
            "S": h(srptools.utils.int_to_bytes(srp_s)),
            "K": srp_hex(sess.key),
            "M1": srp_hex(sess.key_proof),
            "M2": srp_hex(sess.key_proof_hash),
        },
        "hkdf": hkdf,
        "pair_setup": {
            "m1": h(m1),
            "m2": h(m2),
            "m3": h(m3),
            "m4": h(m4),
            "m5": h(m5),
            "m6": h(m6),
            "m5_hkp5": h(m5_hkp5),
            "controller_ltpk": h(setup_srp._auth_public),
            "accessory_ltpk": h(creds.ltpk),
        },
        "pair_verify": {
            "m1": h(v1),
            "m2": h(v2),
            "m3": h(v3),
            "m4": h(v4),
            "shared": h(shared),
            "control_write": h(control_write),
            "control_read": h(control_read),
            "events_write": h(events_write),
            "events_read": h(events_read),
        },
        "hap": {
            "write_key": h(control_write),
            "read_key": h(control_read),
            "sealed_plain": "pattern(1500, 0)",
            "sealed": h(sealed),
            "inbound_plain": ["pattern(1500, 1500)", "pattern(16384, 16384)"],
            "inbound": h(inbound),
        },
        "bplist": bplist,
    }
    with open(out_path, "w") as f:
        json.dump(out, f, indent=1)
        f.write("\n")


if __name__ == "__main__":
    if len(sys.argv) != 2:
        sys.exit(__doc__)
    asyncio.run(main(sys.argv[1]))
